"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1118-01-01:0":{"b": ["दाविद चतुर्थ ने 45.000 क़िपचाक़ परिवारों को जॉर्जिया में बसाना आरंभ किया", "559894b0"], "d": ["दाविद ने उत्तरी काकेशिया और दक्षिणी रूसी स्तेपियों के 45.000 क़िपचाक़ परिवारों से समझौता कर उन्हें 1118 से जॉर्जिया लाना आरंभ किया और उनकी सहायता से 1121 में तिफ़लिस में सल्जूक़ आधिपत्य का अंत किया।", "d4bc7246"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1119-01-01:0":{"b": ["अमीर ग़ाज़ी ने अंताक्या के राजकुमार रोजर को तितर-बितर किया और अंताक्या पर आक्रमण किया", "7bd138a2"], "d": ["अमीर ग़ाज़ी ने मई 1119 में 7000 की सेना के साथ अंताक्या पर आक्रमण किया और अपने ऊपर चढ़ आए अंताक्या के राजकुमार रोजर को तितर-बितर कर दिया।", "c575e81b"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1121-08-12:0":{"b": ["जॉर्जियाई राजा दाविद ने दिदगोरी में मुस्लिम सेना को तितर-बितर किया; तिफ़लिस और अनी का मार्ग खुला", "03b19a6d"], "d": ["जॉर्जियाई राजा दाविद (TDV में द्वितीय दाविद; जॉर्जियाई स्रोतों में चतुर्थ दाविद अगमाशेनेबेली) की क़िपचाक़ों से जुटाई विशाल सेना के विरुद्ध इराक़ी सल्जूक़ सुल्तान महमूद द्वारा भेजे गए गंजा के मलिक तुग़रिल, अताबेग गुंदोग़दी, दुबैस बिन सदक़ा और अर्तुक़ी इल्ग़ाज़ी तथा दिलमाच-ओग़ुल्लारी तोग़ान अर्सलान 12 अगस्त 1121 को दिदगोरी के निकट पराजित हुए। जॉर्जियाइयों ने इसके बाद सदियों से इस्लामी आधिपत्य में रहे तिफ़लिस पर क़ब्ज़ा कर उसे राजधानी बनाया।", "d186cc45"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1122-11-19:0":{"b": ["नज्मुद्दीन इल्ग़ाज़ी की मृत्यु हुई; पुत्र सुलैमान मय्याफ़ारिक़ीन में, तिमुरताश मारदीन में शासन करने लगे", "5e1a6c08"], "d": ["हलब से क्रूसेडरों के विरुद्ध बड़ा संघर्ष करने वाले मारदीन के अर्तुक़ी शासक इल्ग़ाज़ी, भतीजे बेलेक और दमिश्क़ के अताबेग तुग़तेगिन के साथ ज़र्दना दुर्ग के अभियान में बीमार होकर 19 नवंबर 1122 को मरा। उसके पुत्रों में सुलैमान मय्याफ़ारिक़ीन में, तिमुरताश मारदीन में, भतीजा सुलैमान हलब में शासन करता रहा।", "6f429e0c"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1124-01-01:0":{"b": ["अमीर ग़ाज़ी के मलत्या क्षेत्र पर अधिकार से एल्बिस्तान दानिशमंदी प्रशासन में आया", "5be35d74"], "d": ["1114 में बड़े भूकंप से तबाह एल्बिस्तान, 1124 में दानिशमंदी अमीर ग़ाज़ी के मलत्या क्षेत्र पर अधिकार करने से उनके प्रशासन के अधीन आ गया।", "a81725b1"]},
